content.css:
.bullet-chart-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  position: relative;
  box-sizing: border-box;
  user-select: none;
  font-family: "Segoe UI", Arial, sans-serif;
}
.bullet-scroll-area {
  width: 100%;
  height: 100%;
  overflow-x: hidden;
  overflow-y: auto;
}
.bullet-chart-root svg {
  width: 100%;
  height: 100%;
  display: block;
}
.bullet-empty-state {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: #888;
  font-size: 12px;
  text-align: center;
  max-width: 80%;
  pointer-events: none;
}
.bullet-status-blink {
  animation: bulletStatusBlink 1.6s ease-in-out infinite;
}
@keyframes bulletStatusBlink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.25;
  }
}
@media (prefers-reduced-motion: reduce) {
  .bullet-status-blink {
    animation: none;
  }
}
.bullet-tooltip {
  position: absolute;
  z-index: 30;
  pointer-events: none;
  background: rgba(30, 30, 28, 0.94);
  color: #fff;
  border-radius: 4px;
  line-height: 1.5;
  white-space: normal;
  word-break: break-word;
  opacity: 0;
  transition: opacity 0.08s ease;
}
.bullet-license-badge {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 20;
  width: max-content;
  max-width: 92%;
  color: #555;
  background: transparent;
  border: 0;
  overflow: visible;
  font: 800 32px/1 "Segoe UI", Arial, sans-serif;
  text-align: center;
  white-space: nowrap;
  opacity: 0.2;
  pointer-events: none;
  transform: translate(-50%, -50%);
  user-select: none;
}
.bullet-license-badge.invalid {
  color: #9b2c23;
  opacity: 0.22;
}
.bullet-license-badge.licensed {
  left: auto;
  top: 6px;
  right: 6px;
  display: flex;
  width: 22px;
  height: 22px;
  max-width: none;
  align-items: center;
  justify-content: center;
  color: #fff;
  background: rgba(46, 125, 50, 0.88);
  border: 1px solid rgba(27, 94, 32, 0.55);
  border-radius: 50%;
  font: 700 13px/1 "Segoe UI", Arial, sans-serif;
  opacity: 1;
  pointer-events: auto;
  cursor: help;
  transform: none;
}
.bullet-license-notice {
  position: absolute;
  left: 50%;
  bottom: 8px;
  z-index: 21;
  display: none;
  max-width: calc(100% - 24px);
  padding: 4px 9px;
  color: #6b4f00;
  background: rgba(255, 248, 220, 0.92);
  border: 1px solid rgba(174, 126, 0, 0.35);
  border-radius: 4px;
  font: var(--license-notice-base-size, 11px)/1.3 "Segoe UI", Arial, sans-serif;
  text-align: center;
  white-space: nowrap;
  pointer-events: auto;
  cursor: help;
  transform: translateX(-50%);
  transition: bottom 0.18s ease, padding 0.18s ease, font-size 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}
.bullet-license-notice:hover {
  bottom: var(--license-notice-hover-bottom, 28px);
  max-width: calc(100% - 32px);
  padding: 8px 14px;
  font-size: var(--license-notice-hover-size, 18px);
  white-space: normal;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.24);
  transform: translateX(-50%) scale(1.03);
}
